SELECT

FROM userloginidentity
WHERE (
    #{normalizedEmail,jdbcType=VARCHAR} IS NOT NULL
    AND LOWER(email) = #{normalizedEmail,jdbcType=VARCHAR}
)
OR (
    #{normalizedPhone,jdbcType=VARCHAR} IS NOT NULL
    AND phone = #{normalizedPhone,jdbcType=VARCHAR}
)
ORDER BY id
LIMIT 2

SELECT

FROM userloginidentity
WHERE id > #{afterId,jdbcType=BIGINT}
ORDER BY id
LIMIT #{limit,jdbcType=INTEGER}

SELECT EXISTS (
    SELECT 1
    FROM userloginidentity
    WHERE id = #{identityId,jdbcType=BIGINT}
)

