UPDATE userloginidentity
SET github_subject = #{githubSubject,jdbcType=VARCHAR}
WHERE id = #{identityId,jdbcType=BIGINT}
  AND github_subject IS NULL

UPDATE userloginidentity
SET google_subject = #{googleSubject,jdbcType=VARCHAR}
WHERE id = #{identityId,jdbcType=BIGINT}
  AND google_subject IS NULL

UPDATE userloginidentity
SET phone = #{phone,jdbcType=VARCHAR}
WHERE id = #{identityId,jdbcType=BIGINT}
  AND phone IS NULL

UPDATE userloginidentity
SET password_hash = #{passwordHash,jdbcType=VARCHAR}
WHERE id = #{id,jdbcType=BIGINT}

UPDATE userloginidentity
SET password_hash = #{upgradedPasswordHash,jdbcType=VARCHAR}
WHERE id = #{identityId,jdbcType=BIGINT}
  AND password_hash = #{expectedPasswordHash,jdbcType=VARCHAR}

UPDATE userloginidentity
SET totp_secret_encrypted = #{encryptedSecret,jdbcType=VARCHAR},
    totp_enabled = TRUE
WHERE id = #{identityId,jdbcType=BIGINT}
  AND totp_enabled = #{expectedEnabled,jdbcType=BOOLEAN}
  AND totp_secret_encrypted IS NOT DISTINCT FROM
      #{expectedEncryptedSecret,jdbcType=VARCHAR}
